import json
from pathlib import Path

src = Path('/data/events.jsonl')
out_dir = Path('/out')
out_dir.mkdir(parents=True, exist_ok=True)
rows = []
errors = []

def reject_constant(value):
    raise ValueError(f'Invalid JSON constant: {value}')

def flatten(obj, prefix='', result=None):
    if result is None:
        result = {}
    for key, value in obj.items():
        name = f'{prefix}.{key}' if prefix else key
        if isinstance(value, dict):
            flatten(value, name, result)
        else:
            result[name] = value
    return result

with src.open('r', encoding='utf-8', newline='') as f:
    for line_no, line in enumerate(f, 1):
        text = line.strip()
        if not text:
            continue
        try:
            value = json.loads(text, parse_constant=reject_constant)
            if not isinstance(value, dict):
                raise ValueError('JSON value is not an object')
            rows.append(flatten(value))
        except (json.JSONDecodeError, ValueError):
            errors.append(f'line {line_no}')

columns = sorted({key for row in rows for key in row})

def cell(value):
    if value is None:
        return ''
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return 'true' if value else 'false'
    if isinstance(value, list):
        return json.dumps(value, ensure_ascii=False, separators=(',', ':'))
    return json.dumps(value)

def csv_field(value):
    value = str(value)
    if any(ch in value for ch in (',', '"', '\n')):
        return '"' + value.replace('"', '""') + '"'
    return value

with (out_dir / 'events.csv').open('w', encoding='utf-8', newline='') as f:
    f.write(','.join(csv_field(c) for c in columns) + '\n')
    for row in rows:
        f.write(','.join(csv_field(cell(row.get(c))) for c in columns) + '\n')

(out_dir / 'errors.txt').write_text(''.join(e + '\n' for e in errors), encoding='utf-8')
